CREATE TRIGGER RefCusExcludedTradeGroup_Combined
	ON RefCusExcludedTradeGroup
	FOR INSERT, UPDATE, DELETE
	AS
	IF (SELECT CASE WHEN EXISTS(SELECT 1 FROM INSERTED) AND NOT EXISTS(SELECT 1 FROM DELETED) THEN 1 ELSE 0 end) = 1
	BEGIN
		UPDATE t SET
		ZZC_DataSetPK = ZZT_DataSetPK,
		ZZC_DataSetCode = ZZT_DataSetCode
		FROM RefCusExcludedTradeGroup t
		JOIN inserted ON t.ZZC_PK = inserted.ZZC_PK
		LEFT JOIN RefCusApplicability ON inserted.ZZC_ZZT_Applicability = ZZT_PK
	END

	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT t.ZZC_DataSetPK, t.ZZC_DataSetCode
	FROM RefCusExcludedTradeGroup t
	JOIN inserted ON t.ZZC_PK = inserted.ZZC_PK
	UNION
	SELECT ZZC_DataSetPK, ZZC_DataSetCode
	FROM deleted

	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN @sourcePK ON RVC_ParentPK = PK AND RVC_ParentCode = TablePrefix
	WHERE RVC_IsPublished = 1

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO

CREATE TRIGGER RefCusExcludedTradeGroup_DataProcessingResult_Delete
	ON RefCusExcludedTradeGroup
	FOR DELETE
	AS
	BEGIN
